"""视频容器元数据扫描：识别文件自带的 AI 生成标识。

只读取容器元数据（MP4 udta/meta、XMP/C2PA 可打印字段、常见文本标签），
不做画面判断。命中显式 AI 标识或常见生成工具标记时，调用方应直接把视频
判定为 AI 生成，同时仍可继续执行画面模型检测。
"""
from __future__ import annotations

import os
import re
from pathlib import Path
from typing import Any

TEXT_SCAN_BYTES = 2 * 1024 * 1024
MAX_MOOV_BYTES = 64 * 1024 * 1024
MAX_FIELDS = 400
MAX_VALUE_CHARS = 1000
MAX_EVIDENCE_CHARS = 500
MAX_MARKERS = 10
MIN_PRINTABLE_RUN = 4

EXPLICIT_MARKERS = (
    "ai-generated",
    "ai generated",
    "ai_generated",
    "aigc",
    "generated by ai",
    "generated with ai",
    "generative ai",
    "trainedalgorithmicmedia",
    "trained algorithmic media",
    "synthetic media",
    "synthetic video",
    "synthetic content",
    "人工智能生成",
    "ai生成",
    "ai 生成",
    "生成式人工智能",
    "文生视频",
    "图生视频",
    "ai合成",
    "合成视频",
)

TOOL_MARKERS = (
    "sora",
    "openai",
    "runwayml",
    "runway",
    "pika labs",
    "pika.art",
    "kling ai",
    "klingai",
    "kling",
    "hailuo ai",
    "hailuo",
    "dreamina",
    "jimeng",
    "即梦",
    "可灵",
    "海螺",
    "vidu",
    "pixverse",
    "luma dream machine",
    "luma ai",
    "google veo",
    "veo 3",
    "veo3",
    "midjourney",
    "stable video diffusion",
    "stability ai",
    "haiper",
    "genmo",
    "cogvideo",
    "open-sora",
    "opensora",
    "modelscope",
    "animatediff",
    "wan2.1",
    "wan2",
    "hunyuanvideo",
    "混元",
    "通义万相",
    "wanx",
    "seedance",
    "capcut ai",
    "剪映ai",
    "剪映 ai",
    "tencent hunyuan",
    "腾讯混元",
)

SOURCE_PRIORITY = (
    "cmt",
    "comm",
    "des",
    "desc",
    "titl",
    "nam",
    "too",
    "software",
    "encoder",
    "creator",
    "artist",
)

TOOL_SOURCE_HINTS = (
    "too",
    "software",
    "encoder",
    "swr",
    "cmt",
    "comm",
    "des",
    "desc",
    "creator",
    "handler",
)


def scan_video_metadata(path: str | Path) -> dict[str, Any]:
    """扫描视频元数据，返回是否命中 AI 生成标识及证据。"""
    result: dict[str, Any] = {
        "detected": False,
        "status": "ok",
        "source": "",
        "value": "",
        "markers": [],
        "fields": 0,
        "error": "",
    }
    try:
        parsed = _read_mp4_fields(Path(path))
        fallback = _scan_printable_fields(Path(path))
        result["fields"] = len(parsed) + len(fallback)
        matches = _match_fields(parsed, allow_tools=True)
        matches += _match_fields(fallback, allow_tools=False)
        if matches:
            matches.sort(key=lambda item: item["score"], reverse=True)
            best = matches[0]
            result.update(
                detected=True,
                source=best["source"],
                value=best["value"][:MAX_EVIDENCE_CHARS],
                markers=best["markers"][:MAX_MARKERS],
            )
        return result
    except Exception as exc:  # 元数据损坏不应影响检测
        result["status"] = "error"
        result["error"] = str(exc)[:200]
        return result


def _match_fields(
    fields: list[dict[str, str]], *, allow_tools: bool
) -> list[dict[str, Any]]:
    matches = []
    for field in fields:
        text = field.get("value") or ""
        if not text:
            continue
        lower = text.lower()
        found: list[str] = []
        explicit = 0
        source = field.get("source") or ""
        source_lower = source.lower()
        for marker in EXPLICIT_MARKERS:
            if marker in lower and marker not in found:
                found.append(marker)
                explicit += 1
        if allow_tools and any(hint in source_lower for hint in TOOL_SOURCE_HINTS):
            for marker in TOOL_MARKERS:
                if _contains_marker(lower, marker) and marker not in found:
                    found.append(marker)
        if not found:
            continue
        priority = 1 if any(key in source_lower for key in SOURCE_PRIORITY) else 0
        score = explicit * 3 + priority * 2 + min(len(found), 5)
        matches.append(
            {
                "source": source,
                "value": text[:MAX_VALUE_CHARS],
                "markers": found,
                "score": score,
            }
        )
    return matches


def _contains_marker(text: str, marker: str) -> bool:
    if marker.isascii() and len(marker) <= 6 and " " not in marker:
        return re.search(
            rf"(?<![a-z0-9]){re.escape(marker)}(?![a-z0-9])", text
        ) is not None
    return marker in text


def _read_mp4_fields(path: Path) -> list[dict[str, str]]:
    fields: list[dict[str, str]] = []
    payload = _read_moov_payload(path)
    if payload:
        try:
            _walk_boxes(payload, 0, len(payload), ["moov"], fields)
        except Exception:
            pass
    try:
        _read_top_level_metadata(path, fields)
    except Exception:
        pass
    return fields[:MAX_FIELDS]


def _read_top_level_metadata(path: Path, fields: list[dict[str, str]]) -> None:
    try:
        total = path.stat().st_size
    except OSError:
        return
    with path.open("rb") as handle:
        offset = 0
        while offset + 8 <= total and len(fields) < MAX_FIELDS:
            handle.seek(offset)
            header = handle.read(16)
            if len(header) < 8:
                break
            size = int.from_bytes(header[0:4], "big")
            box_type = header[4:8]
            head = 8
            if size == 1:
                if len(header) < 16:
                    break
                size = int.from_bytes(header[8:16], "big")
                head = 16
            elif size == 0:
                size = total - offset
            if size < head or offset + size > total:
                break
            if box_type in {b"udta", b"meta", b"uuid"} and size <= MAX_MOOV_BYTES:
                handle.seek(offset + head)
                data = handle.read(size - head)
                if box_type == b"udta":
                    _walk_boxes(data, 0, len(data), ["file", "udta"], fields)
                elif box_type == b"meta":
                    _walk_boxes(data, 4, len(data), ["file", "meta"], fields)
                else:
                    text = _extract_printable(data)
                    if text and _has_explicit_marker(text):
                        _add_field(fields, ["file", "uuid"], text)
            offset += size


def _read_moov_payload(path: Path) -> bytes:
    try:
        total = path.stat().st_size
    except OSError:
        return b""
    with path.open("rb") as handle:
        offset = 0
        while offset + 8 <= total:
            handle.seek(offset)
            header = handle.read(16)
            if len(header) < 8:
                break
            size = int.from_bytes(header[0:4], "big")
            box_type = header[4:8]
            head = 8
            if size == 1:
                if len(header) < 16:
                    break
                size = int.from_bytes(header[8:16], "big")
                head = 16
            elif size == 0:
                size = total - offset
            if size < head or offset + size > total:
                break
            if box_type == b"moov":
                handle.seek(offset + head)
                return handle.read(min(size - head, MAX_MOOV_BYTES))
            offset += size
    return b""


def _iter_boxes(
    data: bytes, start: int, end: int
):
    offset = start
    while offset + 8 <= end:
        size = int.from_bytes(data[offset : offset + 4], "big")
        box_type = data[offset + 4 : offset + 8]
        head = 8
        if size == 1:
            if offset + 16 > end:
                break
            size = int.from_bytes(data[offset + 8 : offset + 16], "big")
            head = 16
        elif size == 0:
            size = end - offset
        if size < head or offset + size > end:
            break
        yield box_type, offset + head, offset + size
        offset += size


def _walk_boxes(
    data: bytes,
    start: int,
    end: int,
    path: list[str],
    fields: list[dict[str, str]],
) -> None:
    for raw_type, payload_start, payload_end in _iter_boxes(data, start, end):
        name = raw_type.decode("latin1", errors="replace")
        current = path + [name]
        if name in {
            "moov",
            "udta",
            "trak",
            "mdia",
            "minf",
            "stbl",
            "edts",
            "dinf",
        }:
            _walk_boxes(data, payload_start, payload_end, current, fields)
        elif name == "meta":
            _walk_boxes(data, payload_start + 4, payload_end, current, fields)
        elif name == "ilst":
            _parse_ilst(data, payload_start, payload_end, current, fields)
        elif name.startswith("©"):
            text = _extract_text_box(data[payload_start:payload_end])
            if text:
                _add_field(fields, current, text)
        elif name == "uuid":
            text = _extract_printable(data[payload_start:payload_end])
            if text and _has_explicit_marker(text):
                _add_field(fields, current, text)


def _parse_ilst(
    data: bytes,
    start: int,
    end: int,
    path: list[str],
    fields: list[dict[str, str]],
) -> None:
    for raw_type, item_start, item_end in _iter_boxes(data, start, end):
        item_name = raw_type.decode("latin1", errors="replace")
        current = path + [item_name]
        for raw_data_type, data_start, data_end in _iter_boxes(
            data, item_start, item_end
        ):
            if raw_data_type != b"data":
                continue
            text = _extract_data_box(data[data_start:data_end])
            if text:
                _add_field(fields, current, text)


def _extract_text_box(payload: bytes) -> str:
    if not payload:
        return ""
    if len(payload) >= 2:
        length = int.from_bytes(payload[:2], "big")
        if 0 < length <= len(payload) - 2:
            return _decode_text(payload[2 : 2 + length])
    if len(payload) >= 4:
        length = int.from_bytes(payload[:4], "big")
        if 0 < length <= len(payload) - 4:
            return _decode_text(payload[4 : 4 + length])
    return _decode_text(payload)


def _extract_data_box(payload: bytes) -> str:
    if len(payload) >= 8:
        data_type = int.from_bytes(payload[:4], "big") & 0xFFFFFF
        value = payload[8:]
        if data_type == 2:
            return _decode_text(value, utf16=True)
        return _decode_text(value)
    return _decode_text(payload)


def _decode_text(value: bytes, *, utf16: bool = False) -> str:
    value = value.strip(b"\x00")
    if not value:
        return ""
    if utf16 or (b"\x00" in value and len(value) % 2 == 0):
        try:
            text = value.decode("utf-16-be", errors="ignore")
        except Exception:
            text = ""
        if _printable_ratio(text) >= 0.8:
            return _clean_text(text)
    for encoding in ("utf-8", "latin1"):
        try:
            text = value.decode(encoding, errors="ignore")
        except Exception:
            continue
        if _printable_ratio(text) >= 0.8:
            return _clean_text(text)
    return ""


def _clean_text(text: str) -> str:
    text = re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f]+", " ", text)
    text = re.sub(r"\s+", " ", text).strip()
    if len(text) < 3:
        return ""
    return text[:MAX_VALUE_CHARS]


def _printable_ratio(text: str) -> float:
    if not text:
        return 0.0
    printable = sum(
        1 for char in text if char.isprintable() or char in "\t\r\n"
    )
    return printable / len(text)


def _add_field(
    fields: list[dict[str, str]], path: list[str], text: str
) -> None:
    if len(fields) >= MAX_FIELDS:
        return
    text = _clean_text(text)
    if not text:
        return
    source = ".".join(path)
    if any(field["source"] == source and field["value"] == text for field in fields):
        return
    fields.append({"source": source, "value": text})


def _scan_printable_fields(path: Path) -> list[dict[str, str]]:
    try:
        total = path.stat().st_size
    except OSError:
        return []
    chunks = []
    try:
        with path.open("rb") as handle:
            if total <= TEXT_SCAN_BYTES * 2:
                chunks.append(handle.read())
            else:
                chunks.append(handle.read(TEXT_SCAN_BYTES))
                handle.seek(-TEXT_SCAN_BYTES, os.SEEK_END)
                chunks.append(handle.read())
    except OSError:
        return []
    fields: list[dict[str, str]] = []
    seen: set[str] = set()
    for chunk in chunks:
        for encoding in ("utf-8", "utf-16-be", "latin1"):
            try:
                text = chunk.decode(encoding, errors="ignore")
            except Exception:
                continue
            for run in re.findall(
                rf"[ -~]{{{MIN_PRINTABLE_RUN},}}|[\u4e00-\u9fff]{{2,}}", text
            ):
                if run in seen:
                    continue
                seen.add(run)
                value = run[:MAX_VALUE_CHARS]
                fields.append({"source": "container_strings", "value": value})
                if len(fields) >= MAX_FIELDS:
                    return fields
    return fields


def _extract_printable(data: bytes) -> str:
    text = data.decode("latin1", errors="ignore")
    runs = re.findall(rf"[ -~]{{{MIN_PRINTABLE_RUN * 2},}}", text)
    return " ".join(runs)[:MAX_VALUE_CHARS]


def _has_explicit_marker(text: str) -> bool:
    lower = text.lower()
    return any(marker in lower for marker in EXPLICIT_MARKERS)
